begin;create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table closed_source(source uuid,result uuid,corrected uuid);grant select,insert,update on closed_source to cuevo_api;
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','9d100000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Closed source review','Synthetic','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,academic_reference_id,policy_version)values('10000000-0000-4000-8000-000000000001','9d110000-0000-4000-8000-000000000001','9d100000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Closed explanation','School task',10,'61000000-0000-4000-8000-000000000001',2);
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
insert into closed_source(source)select internal.create_learning_submission('9d110000-0000-4000-8000-000000000001','Immutable explanation');select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
update closed_source set result=internal.release_marking(internal.mark_submission(source,3,'Teacher reviewed',2,0,true),1,true);select internal.close_learning_submission((select source from closed_source),1);
select throws_ok($$select internal.mark_submission((select source from closed_source),4,'Ordinary path',2,1,true)$$,'22023',null,'Ordinary academic path remains closed without purpose-specific authority');
select throws_ok($$insert into internal.closed_academic_write_scope values('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004',(select source from closed_source),txid_current(),pg_backend_pid())$$,'42501',null,'Runtime cannot forge the private correction scope');
select throws_ok($$select internal.correct_closed_academic_source((select source from closed_source),jsonb_build_object('score',5,'feedback','Correction','reason','Explicit human review','expectedPolicyVersion',2,'expectedRevision',1,'expectedSubmissionRevision',1,'expectedResultId',(select result from closed_source),'expectedResultRevision',1,'parentVisible',false))$$,'22023',null,'Private correction requires explicit source evidence approval independently of HTTP');
select lives_ok($$update closed_source set corrected=internal.correct_closed_academic_source(source,jsonb_build_object('score',5,'feedback','Reviewed corrected score','reason','Transcription correction','expectedPolicyVersion',2,'expectedRevision',1,'expectedSubmissionRevision',1,'expectedResultId',result,'expectedResultRevision',1,'parentVisible',false,'sourceEvidence',true))$$,'Explicit checked closed correction creates a new release');
select is((select state from app.current_submissions where submission_id=(select source from closed_source)),'CLOSED','Correction does not reopen learner work');
select is(jsonb_array_length(internal.read_academic_revision_page((select corrected from closed_source),100,null)->'items'),2,'Native history retains both result revisions');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select is(jsonb_array_length(internal.read_academic_revision_page((select result from closed_source),100,null)->'items'),1,'Parent history contains only explicitly approved revisions');
reset role;
select is((select count(*)from internal.closed_academic_write_scope),0::bigint,'Correction capability is removed before returning');
select ok(not has_table_privilege('cuevo_api','app.academic_correction_records','SELECT,INSERT,UPDATE,DELETE'),'Correction records remain private from raw runtime access');
select ok(not has_function_privilege('authenticated','internal.correct_closed_academic_source(uuid,jsonb)','EXECUTE'),'Browser cannot invoke private correction command');
select ok(not has_function_privilege('cuevo_worker','internal.correct_closed_academic_source(uuid,jsonb)','EXECUTE'),'Worker has no academic correction authority');
select*from finish();rollback;
